cd ~ && cat > /Users/kristinarash/.claude/jobs/71bdf0a0/tmp/fm.py <<'EOF'
import sys, os, glob, yaml, collections
def fm(path):
    try: t=open(path,encoding='utf-8',errors='replace').read()
    except Exception as e: return None,'read:'+str(e)
    if not t.startswith('---'): return None,'nofm'
    parts=t.split('\n---',1)
    if len(parts)<2: return None,'unterminated'
    block=parts[0][3:]
    try: d=yaml.safe_load(block) or {}
    except Exception as e: return None,'yaml:'+str(e).split('\n')[0]
    return d,None
print("== agents")
for d in [os.path.expanduser('~/.claude/agents'), os.path.expanduser('~/DEV/.claude/agents')]:
    names=collections.defaultdict(list)
    for p in glob.glob(d+'/**/*.md',recursive=True):
        f,err=fm(p)
        if err: print('ERR',p,err); continue
        if not isinstance(f,dict) or 'name' not in f: continue
        if not f.get('description'): print('NODESC',p)
        names[(os.path.dirname(p),str(f['name']))].append(p)
    for k,v in names.items():
        if len(v)>1: print('COLLIDE',k,v)
    print(d, sum(len(v) for v in names.values()),'agents')
print("== skills")
for d in [os.path.expanduser('~/.claude/skills'), os.path.expanduser('~/DEV/.claude/skills')]:
    n=0
    for p in glob.glob(d+'/*/SKILL.md'):
        n+=1
        f,err=fm(p)
        if err: print('ERR',p,err)
        elif not isinstance(f,dict): print('NOTDICT',p)
        elif not f.get('description'): print('NODESC',p)
    print(d,n,'skills')
EOF
uv run --quiet --with pyyaml python3 -I /Users/kristinarash/.claude/jobs/71bdf0a0/tmp/fm.py 2>&1 | tail -40

