import json, glob, os, re, collections, time, statistics
files=sorted(glob.glob(os.path.expanduser('~/.claude/projects/*/*.jsonl')), key=os.path.getmtime, reverse=True)[:50]
mt=[os.path.getmtime(f) for f in files]
print("window: %d sessions, %.1f days (oldest %s)"%(len(files),(time.time()-min(mt))/86400, time.strftime('%Y-%m-%d',time.localtime(min(mt)))))
skills=collections.Counter(); slash=collections.Counter(); mcp=collections.Counter(); hooks=collections.defaultdict(list); hookerr=collections.Counter(); timeouts=collections.Counter()
tooluse={}; denials=[]; fallback=[]
cmdre=re.compile(r'<command-name>/?([^<]+)</command-name>')
for f in files:
    for line in open(f,errors='replace'):
        try: o=json.loads(line)
        except: continue
        t=o.get('type')
        if t=='assistant':
            for c in (o.get('message') or {}).get('content') or []:
                if isinstance(c,dict) and c.get('type')=='tool_use':
                    n=c.get('name',''); tooluse[c.get('id')]=(n,c.get('input') or {})
                    if n=='Skill': skills[str((c.get('input') or {}).get('skill'))]+=1
                    if n.startswith('mcp__'): mcp[n.split('__')[1]]+=1
        elif t=='user':
            m=o.get('message') or {}
            cont=m.get('content')
            s=cont if isinstance(cont,str) else json.dumps(cont) if cont else ''
            for x in cmdre.findall(s[:2000]): slash[x.strip()]+=1
            k=o.get('toolDenialKind')
            if isinstance(cont,list):
                for c in cont:
                    if isinstance(c,dict) and c.get('type')=='tool_result':
                        if k and k not in ('interrupted','cancelled'):
                            denials.append((k,c.get('tool_use_id')))
                        elif not k and c.get('is_error'):
                            txt=json.dumps(c.get('content'))[:300]
                            if "doesn't want to proceed" in txt or 'Permission to use' in txt or 'Permission for this' in txt:
                                fallback.append(c.get('tool_use_id'))
        elif t=='attachment':
            a=o.get('attachment') or {}
            if a.get('type','').startswith('hook_'):
                key=(a.get('hookEvent'),a.get('hookName'),(a.get('command') or '')[:90])
                if a.get('durationMs') is not None: hooks[key].append(a['durationMs'])
                if a['type']!='hook_success': hookerr[(key,a['type'])]+=1
                if a.get('timedOut'): timeouts[key]+=1
print("\n== Skill tool:",skills.most_common())
print("\n== slash:",slash.most_common(60))
print("\n== mcp servers:",mcp.most_common())
print("\n== hooks (n, median, p95/max ms)")
for k,v in sorted(hooks.items(), key=lambda kv:-statistics.median(kv[1])):
    v=sorted(v); print(len(v), int(statistics.median(v)), v[int(len(v)*.95)-1 if len(v)>1 else 0], v[-1], k)
print("\n== hook non-success:",[(k[0][0],k[0][1],k[1],n) for k,n in hookerr.items()])
print("== timeouts:",dict(timeouts))
def key(n,i):
    if n=='Bash':
        p=(i.get('command') or '').split(); return 'Bash: '+' '.join(p[:2])
    return n
dc=collections.defaultdict(collections.Counter)
for k,tid in denials:
    n,i=tooluse.get(tid,('?',{})); dc[key(n,i)][k]+=1
print("\n== denials (CLI-stamped):")
for p,c in sorted(dc.items(), key=lambda kv:-sum(kv[1].values()))[:25]: print(sum(c.values()),dict(c),p)
fc=collections.Counter()
for tid in fallback:
    n,i=tooluse.get(tid,('?',{}))
    if not n.startswith('mcp__'): fc[key(n,i)]+=1
print("\n== fallback denials (unverified):",fc.most_common(15))
EOF
cd ~ && python3 -I /Users/kristinarash/.claude/jobs/71bdf0a0/tmp/scan.py

